const PUR=[['deliv','Material delivery','<path d="M3 7h11v9H3z"/><path d="M14 10h4l3 3v3h-7"/><circle cx="7" cy="17.5" r="1.8"/><circle cx="17" cy="17.5" r="1.8"/>'],['pick','Pickup','<path d="M12 3v11"/><path d="M8 10l4 4 4-4"/><path d="M4 17v3h16v-3"/>'],['mob','Mobilize','<path d="M5 21V4"/><path d="M5 4h11l-2 4 2 4H5"/>'],['demob','Demobilize','<path d="M9 14L4 9l5-5"/><path d="M4 9h10.5a5.5 5.5 0 0 1 0 11H11"/>']];const purL=k=>(PUR.find(x=>x[0]===k)||[])[1]||'';
